INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('zuzu-angel','Zuzu Angel',2006,'Sérgio Rezende',6.8,'A estilista Zuzu Angel enfrenta o regime militar para descobrir o paradeiro do filho Stuart, preso e morto pelos órgãos de repressão.','Use para resistência civil, papel da mulher e denúncia internacional de violações.','Zuzu Angel (2006) mostra que a persistência de uma mãe transformou luto em denúncia pública contra os crimes da ditadura.','desenvolvimento','from-cyan-500/30 to-slate-900/60','https://upload.wikimedia.org/wikipedia/pt/b/b9/Zuzu_Angel_%28filme%29.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('batismo-de-sangue','Batismo de Sangue',2006,'Helvécio Ratton',6.5,'Frades dominicanos que apoiam a luta armada contra a ditadura são presos e torturados no final dos anos 1960.','Útil para discutir tortura, intolerância política e o papel da Igreja diante do autoritarismo.','Batismo de Sangue (2006) evidencia que a tortura, ao ser tolerada pelo Estado, corrói os valores éticos e religiosos que a própria sociedade diz defender.','desenvolvimento','from-yellow-600/30 to-emerald-900/50','https://upload.wikimedia.org/wikipedia/en/d/de/Baptism_of_Blood_film.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('argentina-1985','Argentina, 1985',2022,'Santiago Mitre',7.2,'Promotores jovens e com poucos recursos enfrentam o julgamento dos comandantes da ditadura argentina.','Use como exemplo de justiça de transição e responsabilização de violadores de direitos humanos.','Argentina, 1985 (2022) demonstra que julgar os crimes do passado é condição para fortalecer a democracia e evitar a repetição da barbárie.','conclusao','from-red-600/30 to-neutral-900/60','https://upload.wikimedia.org/wikipedia/pt/a/af/Argentina_1985.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('no','No',2012,'Pablo Larraín',7.4,'Um publicitário comanda a campanha do ''Não'' no plebiscito de 1988 que decidiu o fim da ditadura de Pinochet.','Use para o poder da comunicação, da publicidade e da participação popular na política.','No (2012) revela que a mobilização democrática também se constrói pela linguagem e pela esperança, e não apenas pelo confronto.','desenvolvimento','from-violet-600/30 to-emerald-900/50','https://upload.wikimedia.org/wikipedia/pt/7/70/No-P%C3%B4ster.png');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('corra','Corra!',2017,'Jordan Peele',7.7,'Um fotógrafo negro visita a família da namorada branca e descobre que a gentileza dos anfitriões esconde algo perturbador.','Use para racismo estrutural disfarçado de simpatia e para a objetificação do corpo negro.','Corra! (2017) denuncia que o racismo nem sempre se manifesta como hostilidade aberta: muitas vezes se esconde em elogios e estereótipos aparentemente inofensivos.','desenvolvimento','from-rose-400/30 to-amber-900/50','https://upload.wikimedia.org/wikipedia/pt/0/02/Get_Out_2017.png');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('moonlight-sob-a-luz-do-luar','Moonlight: Sob a Luz do Luar',2016,'Barry Jenkins',7.4,'Em três fases da vida, Chiron cresce em um bairro pobre de Miami enquanto descobre sua identidade e a sexualidade.','Serve para interseção entre raça, pobreza e identidade LGBTQIA+, além de masculinidade.','Moonlight (2016) mostra que a combinação de pobreza, racismo e homofobia multiplica as barreiras para que jovens construam a própria identidade.','desenvolvimento','from-lime-500/30 to-stone-900/60','https://upload.wikimedia.org/wikipedia/pt/f/f3/Moonlight_%28filme%29.png');
