INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('luta-por-justica','Luta por Justiça',2019,'Destin Daniel Cretton',7.6,'O advogado Bryan Stevenson defende Walter McMillian, homem negro condenado à morte no Alabama sem provas consistentes.','Use para viés racial no sistema de justiça e encarceramento seletivo.','Luta por Justiça (2019) mostra que, quando o sistema penal é atravessado pelo racismo, a pena de morte recai sobre quem tem menos acesso à defesa.','desenvolvimento','from-red-700/40 to-zinc-900/60','https://upload.wikimedia.org/wikipedia/en/1/1b/Just_Mercy_Official_Poster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('o-odio-que-voce-semeia','O Ódio que Você Semeia',2018,'George Tillman Jr.',7.5,'Starr, adolescente negra, presencia a morte de um amigo desarmado pela polícia e precisa decidir se vai depor.','Serve para violência policial, silenciamento e dupla vida de jovens negros.','O Ódio que Você Semeia (2018) revela que a violência policial contra jovens negros alimenta ciclos de medo e revolta nas periferias.','desenvolvimento','from-rose-700/40 to-slate-900/60','https://upload.wikimedia.org/wikipedia/pt/c/c2/TheHateUGive.png');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('a-13a-emenda','A 13ª Emenda',2016,'Ava DuVernay',8.2,'Documentário sobre como a Constituição americana abriu brecha para a escravidão por meio do encarceramento em massa.','Use para ligar escravidão, racismo e sistema prisional, com dados concretos.','A 13ª Emenda (2016) demonstra que o fim legal da escravidão deu lugar a novas formas de controle da população negra, como o encarceramento em massa.','desenvolvimento','from-stone-500/30 to-red-900/50','https://upload.wikimedia.org/wikipedia/pt/d/d6/13th_%28filme%29.png');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('eu-nao-sou-seu-negro','Eu Não Sou Seu Negro',2016,'Raoul Peck',7.9,'Documentário baseado em escritos de James Baldwin sobre a história do racismo nos Estados Unidos.','Bom para repertório de autores, memória e pensamento antirracista.','Eu Não Sou Seu Negro (2016) mostra, a partir de James Baldwin, que o racismo é um problema da sociedade inteira e não apenas de quem o sofre.','introducao','from-fuchsia-600/30 to-slate-900/60','https://upload.wikimedia.org/wikipedia/en/3/31/I_Am_Not_Your_Negro.png');
