INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('distrito-9','Distrito 9',2009,'Neill Blomkamp',7.9,'Alienígenas refugiados são confinados em um gueto em Joanesburgo e sofrem segregação e exploração.','Serve como alegoria do apartheid, da xenofobia e do tratamento dado a refugiados.','Distrito 9 (2009) funciona como alegoria de que a segregação transforma o diferente em ameaça e justifica a negação de direitos básicos.','desenvolvimento','from-emerald-500/30 to-zinc-900/60','https://upload.wikimedia.org/wikipedia/pt/d/d7/District_nine_ver2.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('medida-provisoria','Medida Provisória',2022,'Lázaro Ramos',6.5,'Em um Brasil distópico, o governo obriga cidadãos negros a serem ''devolvidos'' à África, e a resistência cresce.','Use para racismo estrutural, reparação histórica e discriminação institucionalizada.','Medida Provisória (2022) exagera a ficção para expor uma verdade brasileira: a desigualdade racial é sustentada por estruturas, e não por casos isolados.','desenvolvimento','from-blue-500/30 to-fuchsia-900/50','https://upload.wikimedia.org/wikipedia/pt/e/ed/Medida_Provis%C3%B3ria_2022.jpeg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('doutor-gama','Doutor Gama',2021,'Jefferson De',6.9,'Biografia de Luiz Gama, ex-escravizado que se tornou advogado e libertou centenas de pessoas na Justiça.','Bom para abolicionismo, acesso à educação e uso do direito como resistência.','Doutor Gama (2021) mostra que o conhecimento jurídico foi uma arma contra a escravidão e que o acesso ao ensino transforma a vida de grupos excluídos.','desenvolvimento','from-rose-500/30 to-orange-900/50','https://upload.wikimedia.org/wikipedia/pt/d/d5/Doutor_Gama.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('tropa-de-elite','Tropa de Elite',2007,'José Padilha',8.0,'O capitão Nascimento, do BOPE, combate o tráfico no Rio enquanto convive com corrupção policial e consumo de drogas pela classe média.','Use para segurança pública, corrupção e responsabilidade do consumidor de drogas.','Tropa de Elite (2007) evidencia que a violência urbana é sustentada por uma cadeia que envolve tráfico, corrupção policial e consumo, e não apenas as favelas.','desenvolvimento','from-indigo-400/30 to-slate-900/60','https://upload.wikimedia.org/wikipedia/pt/2/2a/TropaDeElitePoster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('tropa-de-elite-2','Tropa de Elite 2',2010,'José Padilha',8.0,'O agora coronel Nascimento descobre que milícias, políticos e policiais corruptos formam um sistema maior que o tráfico.','Serve para milícias, corrupção política e falhas do sistema de segurança.','Tropa de Elite 2 (2010) revela que o verdadeiro inimigo da segurança pública é um sistema político que lucra com a violência.','desenvolvimento','from-amber-500/30 to-emerald-950/60','https://upload.wikimedia.org/wikipedia/pt/e/ed/Tropa_de_Elite_2.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('onibus-174','Ônibus 174',2002,'José Padilha e Felipe Lacerda',8.0,'Documentário sobre o sequestro de um ônibus no Rio de Janeiro e a trajetória de Sandro, sobrevivente da chacina da Candelária.','Use para invisibilidade social, crianças em situação de rua e falhas do Estado.','Ônibus 174 (2002) mostra que a invisibilidade social produz violência: quem nunca foi visto pelo Estado exige, de modo trágico, ser notado.','desenvolvimento','from-orange-500/30 to-stone-900/60','https://upload.wikimedia.org/wikipedia/pt/4/46/%C3%94nibus_174.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('pixote-a-lei-do-mais-fraco','Pixote: A Lei do Mais Fraco',1981,'Hector Babenco',7.9,'Meninos de rua passam por um reformatório em São Paulo e entram em um ciclo de crime e violência.','Serve para abandono infantil, falência das instituições de correção e criminalização da pobreza.','Pixote (1981) revela que instituições que deveriam proteger crianças acabam reproduzindo a violência que dizem combater.','desenvolvimento','from-yellow-500/30 to-neutral-900/60','https://upload.wikimedia.org/wikipedia/pt/9/94/Pixote%2C_a_lei_do_mais_fraco.png');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('marte-um','Marte Um',2022,'Gabriel Martins',7.4,'Uma família negra da periferia de Belo Horizonte busca sonhos e afeto em meio a dificuldades após a eleição de 2018.','Bom para afeto, esperança e dignidade dentro das desigualdades urbanas.','Marte Um (2022) mostra que, mesmo diante da desigualdade, as famílias periféricas constroem projetos de futuro baseados em afeto e solidariedade.','conclusao','from-teal-400/30 to-purple-950/60','https://upload.wikimedia.org/wikipedia/pt/e/ea/Marte_Um_2022.jpeg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('o-som-ao-redor','O Som ao Redor',2012,'Kleber Mendonça Filho',7.0,'A rotina de uma rua de classe média no Recife é alterada pela chegada de uma equipe de segurança privada.','Use para medo urbano, herança escravocrata nas relações sociais e segurança privada.','O Som ao Redor (2012) mostra que o medo da violência produz uma cidade murada, em que a segurança vira mercadoria e a convivência desaparece.','desenvolvimento','from-cyan-400/30 to-rose-900/50','https://upload.wikimedia.org/wikipedia/pt/7/74/O_Som_ao_Redor.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('quanto-vale-ou-e-por-quilo','Quanto Vale ou É por Quilo?',2005,'Sérgio Bianchi',7.2,'Compara a escravidão colonial com o ''marketing social'' de organizações que lucram com a miséria.','Ótimo para crítica ao assistencialismo e à mercantilização da solidariedade.','Quanto Vale ou É por Quilo? (2005) denuncia que a pobreza vira negócio quando a solidariedade é tratada como produto de marketing.','desenvolvimento','from-blue-400/30 to-zinc-950/60','https://upload.wikimedia.org/wikipedia/pt/9/9d/Quanto_Vale_ou_%C3%89_por_Quilo.jpeg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('capitaes-da-areia','Capitães da Areia',2011,'Cecília Amado e Guy Gonçalves',6.7,'Meninos abandonados vivem em um trapiche em Salvador e sobrevivem de pequenos crimes nos anos 1930.','Use para infância abandonada e para a obra de Jorge Amado como repertório literário.','Capitães da Areia (2011) mostra que a ausência de proteção social empurra crianças para uma vida marcada pela exclusão.','desenvolvimento','from-red-400/30 to-indigo-950/60','https://upload.wikimedia.org/wikipedia/pt/3/3c/Capit%C3%A3es_da_Areia_%28filme%29.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('trash-a-esperanca-vem-do-lixo','Trash: A Esperança Vem do Lixo',2014,'Stephen Daldry',7.0,'Meninos que vivem de catar lixo no Rio encontram uma carteira que revela um esquema de corrupção política.','Serve para corrupção, trabalho infantil e resíduos sólidos.','Trash (2014) revela que os catadores de lixo, tratados como invisíveis, podem ser testemunhas das injustiças que a sociedade prefere ignorar.','desenvolvimento','from-purple-500/30 to-stone-950/60','https://upload.wikimedia.org/wikipedia/pt/a/a9/Trash_-_A_Esperan%C3%A7a_Vem_do_Lixo.png');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('quem-quer-ser-um-milionario','Quem Quer Ser um Milionário?',2008,'Danny Boyle',8.0,'Jamal, jovem das favelas de Mumbai, chega à final de um programa de perguntas e respostas usando o que viveu.','Use para desigualdade, conhecimento além da escola e mobilidade social.','Quem Quer Ser um Milionário? (2008) evidencia que o conhecimento nasce também da experiência, mas que a mobilidade social ainda depende de sorte quando faltam políticas públicas.','desenvolvimento','from-amber-400/30 to-cyan-950/60','https://upload.wikimedia.org/wikipedia/pt/8/82/Slumdog_Millionaire_2008.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('expresso-do-amanha','Expresso do Amanhã',2013,'Bong Joon-ho',7.1,'Em um trem que circula por um planeta congelado, os passageiros são divididos em classes rígidas, e os últimos se rebelam.','Use como alegoria da desigualdade e da divisão de classes.','Expresso do Amanhã (2013) é uma alegoria de que a desigualdade extrema se mantém quando os privilegiados controlam os recursos e a narrativa.','desenvolvimento','from-orange-400/30 to-blue-950/60','https://upload.wikimedia.org/wikipedia/pt/d/de/Snowpiercer.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('em-busca-da-felicidade','Em Busca da Felicidade',2006,'Gabriele Muccino',8.0,'Chris Gardner luta contra a falta de moradia ao lado do filho enquanto tenta se tornar corretor de valores.','Cuidado: o filme costuma ser usado como argumento de meritocracia. Use para discutir limites do esforço individual.','Em Busca da Felicidade (2006) mostra que, embora o esforço individual transforme trajetórias, a ausência de proteção social torna a ascensão um caminho de enorme custo.','desenvolvimento','from-yellow-400/30 to-teal-950/60','https://upload.wikimedia.org/wikipedia/pt/1/1e/The_Pursuit_of_Happyness.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('dois-dias-uma-noite','Dois Dias, Uma Noite',2014,'Jean-Pierre e Luc Dardenne',7.3,'Uma operária tem um fim de semana para convencer os colegas a abrir mão de bônus e salvar seu emprego.','Bom para ética no trabalho, desemprego e saúde mental.','Dois Dias, Uma Noite (2014) revela que a lógica do lucro coloca os trabalhadores uns contra os outros e corrói a solidariedade.','desenvolvimento','from-pink-500/30 to-indigo-950/60','https://upload.wikimedia.org/wikipedia/pt/0/0f/Deux_jours%2C_une_nuit.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('clube-da-luta','Clube da Luta',1999,'David Fincher',8.8,'Um funcionário insone cria com um desconhecido um clube secreto de lutas que cresce até virar movimento de contestação ao consumismo.','Use para consumismo, alienação e crise de identidade masculina.','Clube da Luta (1999) critica uma sociedade em que o valor das pessoas se mede pelo que elas consomem, gerando vazio e alienação.','desenvolvimento','from-amber-300/30 to-slate-950/60','https://upload.wikimedia.org/wikipedia/pt/2/2b/FightClubPoster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('a-grande-aposta','A Grande Aposta',2015,'Adam McKay',7.8,'Investidores percebem a bolha imobiliária americana e apostam contra o mercado antes da crise de 2008.','Ótimo para crise financeira, ganância e fiscalização do mercado.','A Grande Aposta (2015) mostra que a falta de regulação e a ganância de poucos podem arrastar milhões de pessoas para a crise.','desenvolvimento','from-sky-400/30 to-violet-950/60','https://upload.wikimedia.org/wikipedia/pt/7/76/The_Big_Short.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('metropolis','Metrópolis',1927,'Fritz Lang',8.3,'Em uma cidade futurista, os operários vivem no subsolo enquanto a elite desfruta da superfície.','Clássico do cinema mudo para industrialização, divisão de classes e mecanização do trabalhador.','Metrópolis (1927) antecipa o debate sobre industrialização ao mostrar que o progresso técnico, sem justiça social, aprofunda a separação entre as classes.','introducao','from-orange-300/30 to-blue-950/60','https://upload.wikimedia.org/wikipedia/pt/c/ca/Metropolis_poster_promocional.png');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('ex-machina','Ex Machina',2014,'Alex Garland',7.7,'Um jovem programador é convidado a testar a consciência de uma androide criada por um bilionário.','Use para inteligência artificial, ética tecnológica e poder das grandes empresas de tecnologia.','Ex Machina (2014) levanta que o avanço da inteligência artificial exige regras éticas claras, para que a tecnologia não sirva ao poder de poucos.','desenvolvimento','from-orange-500/30 to-stone-900/60','https://upload.wikimedia.org/wikipedia/pt/3/32/Ex_Machina.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('matrix','Matrix',1999,'Lilly e Lana Wachowski',8.7,'Um programador descobre que a realidade é uma simulação criada por máquinas para controlar a humanidade.','Serve para alienação digital, controle da informação e dependência da tecnologia.','Matrix (1999) funciona como metáfora de uma sociedade que, imersa em telas, pode confundir o real com a ilusão e perder a capacidade crítica.','introducao','from-yellow-500/30 to-neutral-900/60','https://upload.wikimedia.org/wikipedia/pt/c/c1/The_Matrix_Poster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('a-rede-social','A Rede Social',2010,'David Fincher',7.8,'A criação do Facebook por Mark Zuckerberg e as disputas entre amigos e sócios.','Use para redes sociais, ambição e relações no mundo digital.','A Rede Social (2010) mostra que a plataforma que prometia aproximar pessoas nasceu de disputas, e que o mundo digital reflete conflitos reais.','introducao','from-blue-400/30 to-zinc-950/60','https://upload.wikimedia.org/wikipedia/pt/b/b2/A_Rede_Social.png');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('o-show-de-truman','O Show de Truman',1998,'Peter Weir',8.2,'Truman vive sem saber que toda a sua vida é um programa de televisão.','Use para exposição da vida privada, manipulação midiática e cultura do espetáculo.','O Show de Truman (1998) antecipa uma sociedade em que a privacidade vira espetáculo e a mídia molda a percepção da realidade.','desenvolvimento','from-purple-500/30 to-stone-950/60','https://upload.wikimedia.org/wikipedia/pt/8/85/TheTrumanShow.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('requiem-para-um-sonho','Réquiem para um Sonho',2000,'Darren Aronofsky',8.3,'Quatro personagens têm a vida destruída pelo vício em diferentes drogas.','Use para dependência química e saúde mental, com cuidado e dados do Ministério da Saúde.','Réquiem para um Sonho (2000) mostra que o vício, de drogas ou de qualquer tipo, destrói vínculos e exige tratamento e acolhimento.','desenvolvimento','from-amber-300/30 to-slate-950/60','https://upload.wikimedia.org/wikipedia/pt/9/92/Requiem_for_a_dream.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('meu-pai','Meu Pai',2020,'Florian Zeller',8.2,'Anthony, idoso com demência, vive a confusão do tempo e dos espaços enquanto a filha tenta cuidar dele.','Use para Alzheimer, envelhecimento e sobrecarga de cuidadores.','Meu Pai (2020) mostra que o envelhecimento com demência exige políticas de cuidado, pois sobrecarrega as famílias.','desenvolvimento','from-orange-300/30 to-blue-950/60','https://upload.wikimedia.org/wikipedia/pt/2/2d/The_Father.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('o-jogo-da-imitacao','O Jogo da Imitação',2014,'Morten Tyldum',8.0,'Alan Turing decifra o código nazista e, anos depois, é condenado por ser homossexual.','Use para ciência, contribuição de minorias e perseguição a pessoas LGBTQIA+.','O Jogo da Imitação (2014) evidencia que a intolerância priva a sociedade de talentos: o homem que ajudou a vencer a guerra foi punido por ser quem era.','desenvolvimento','from-slate-400/30 to-slate-950/60','https://upload.wikimedia.org/wikipedia/pt/1/1a/O_Jogo_da_Imita%C3%A7%C3%A3o.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('divertida-mente','Divertida Mente',2015,'Pete Docter',8.1,'Cinco emoções comandam a mente de Riley, uma menina de 11 anos que se muda de cidade.','Serve para saúde emocional, infância e importância de acolher a tristeza.','Divertida Mente (2015) ensina que acolher todas as emoções, inclusive a tristeza, é fundamental para a saúde mental na infância.','introducao','from-emerald-500/30 to-amber-950/60','https://upload.wikimedia.org/wikipedia/pt/f/f6/Inside_Out_%28filme%29.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('um-sonho-de-liberdade','Um Sonho de Liberdade',1994,'Frank Darabont',9.3,'Andy Dufresne, condenado injustamente, constrói amizade e esperança durante décadas em uma prisão.','Use para sistema prisional, corrupção e esperança.','Um Sonho de Liberdade (1994) mostra que o sistema prisional que apenas pune destrói a dignidade, e que a esperança é força de resistência.','desenvolvimento','from-amber-700/40 to-neutral-950/60','https://upload.wikimedia.org/wikipedia/pt/d/d2/The_Shawshank_Redemption_p%C3%B4ster.png');
