INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('os-ultimos-passos-de-um-homem','Os Últimos Passos de um Homem',1995,'Tim Robbins',7.5,'Uma freira acompanha um condenado à morte e o confronta com o sofrimento das vítimas.','Use para debate sobre pena de morte com visões diferentes.','Os Últimos Passos de um Homem (1995) coloca em debate a pena de morte ao mostrar o sofrimento das vítimas e a humanidade de quem é condenado.','conclusao','from-lime-600/30 to-emerald-950/60','https://upload.wikimedia.org/wikipedia/pt/a/aa/Dead_Man_Walking_-_poster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('12-homens-e-uma-sentenca','12 Homens e uma Sentença',1957,'Sidney Lumet',9.0,'Doze jurados debatem se um jovem acusado de assassinato é culpado, e um deles resiste ao consenso.','Clássico para presunção de inocência, preconceito e deliberação democrática.','12 Homens e uma Sentença (1957) mostra que o preconceito pode contaminar julgamentos, e que a dúvida razoável é garantia essencial da justiça.','desenvolvimento','from-teal-500/30 to-stone-950/60','https://upload.wikimedia.org/wikipedia/commons/b/b5/12_Angry_Men_%281957_film_poster%29.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('hannah-arendt','Hannah Arendt',2012,'Margarethe von Trotta',7.0,'A filósofa cobre o julgamento do nazista Eichmann e formula o conceito de ''banalidade do mal''.','Use para banalidade do mal, obediência cega e responsabilidade individual.','Hannah Arendt (2012) mostra que atrocidades podem ser cometidas por pessoas comuns que deixam de pensar criticamente e apenas obedecem.','desenvolvimento','from-indigo-500/30 to-red-950/60','https://upload.wikimedia.org/wikipedia/pt/6/66/Hannah_Arendt_filme.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('a-lista-de-schindler','A Lista de Schindler',1993,'Steven Spielberg',9.0,'O empresário Oskar Schindler salva mais de mil judeus durante o Holocausto.','Clássico para Holocausto, intolerância e ações individuais de solidariedade.','A Lista de Schindler (1993) mostra que, diante do horror, escolhas individuais de solidariedade podem salvar vidas.','desenvolvimento','from-blue-600/30 to-stone-950/60','https://upload.wikimedia.org/wikipedia/pt/1/1d/SchindlerPoster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('o-pianista','O Pianista',2002,'Roman Polanski',8.5,'Um pianista judeu sobrevive escondido no gueto de Varsóvia durante a Segunda Guerra.','Serve para Holocausto, memória e sobrevivência.','O Pianista (2002) revela que o Holocausto foi um processo de desumanização que só foi possível pela indiferença de muitos.','desenvolvimento','from-rose-500/30 to-indigo-950/60','https://upload.wikimedia.org/wikipedia/pt/0/0d/ThePianistPoster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('o-grande-ditador','O Grande Ditador',1940,'Charles Chaplin',8.4,'Uma sátira ao nazismo em que um barbeiro judeu é confundido com um ditador.','Use para sátira política, discursos de ódio e o famoso discurso final.','O Grande Ditador (1940) mostra que o humor pode ser uma arma contra o autoritarismo, ao ridicularizar a lógica da intolerância.','introducao','from-amber-500/30 to-rose-700/40','https://upload.wikimedia.org/wikipedia/commons/9/9d/The_Great_Dictator_%281940%29_poster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('nada-de-novo-no-front','Nada de Novo no Front',2022,'Edward Berger',7.8,'Jovens soldados alemães descobrem a brutalidade da Primeira Guerra Mundial.','Serve para crítica à guerra e manipulação da juventude.','Nada de Novo no Front (2022) evidencia que a guerra sacrifica jovens em nome de ideais que os governos defendem de longe.','desenvolvimento','from-orange-600/40 to-red-900/50','https://upload.wikimedia.org/wikipedia/en/c/c3/All_quiet_on_the_western_front_%282022_film%29.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('fogo-no-mar','Fogo no Mar',2016,'Gianfranco Rosi',7.4,'Documentário sobre a ilha de Lampedusa, porta de entrada de refugiados na Europa, e a vida dos moradores.','Use para crise migratória e indiferença diante do sofrimento de refugiados.','Fogo no Mar (2016) mostra que a tragédia dos refugiados convive, lado a lado, com a indiferença de sociedades que preferem não enxergá-la.','desenvolvimento','from-sky-500/30 to-indigo-800/50','https://upload.wikimedia.org/wikipedia/en/e/ee/Fire_at_Sea.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('cinema-paradiso','Cinema Paradiso',1988,'Giuseppe Tornatore',8.5,'Um cineasta relembra a infância na Sicília e a amizade com o projecionista do cinema local.','Use para cultura, memória e importância do cinema como espaço de encontro.','Cinema Paradiso (1988) mostra que a cultura é espaço de encontro e que perder equipamentos culturais empobrece a vida em comunidade.','conclusao','from-cyan-500/30 to-slate-900/60','https://upload.wikimedia.org/wikipedia/pt/3/3c/Nuovo_Cinema_Paradiso.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('o-auto-da-compadecida','O Auto da Compadecida',2000,'Guel Arraes',8.7,'Os astutos João Grilo e Chicó enfrentam a pobreza do sertão nordestino com humor e fé.','Serve para cultura popular nordestina, desigualdade e sátira social.','O Auto da Compadecida (2000) revela, com humor, as desigualdades do sertão e valoriza a cultura popular como forma de resistência.','introducao','from-yellow-600/30 to-emerald-900/50','https://upload.wikimedia.org/wikipedia/pt/b/bf/O_auto_da_compadecida.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('cabra-marcado-para-morrer','Cabra Marcado para Morrer',1984,'Eduardo Coutinho',8.2,'Documentário que retoma as filmagens interrompidas pelo golpe de 1964 e reencontra a família do líder camponês João Pedro Teixeira.','Ótimo para memória, luta pela terra e ditadura.','Cabra Marcado para Morrer (1984) mostra que a repressão política interrompeu vidas e filmes, mas a memória permite reconstruir o que o autoritarismo tentou apagar.','desenvolvimento','from-red-600/30 to-neutral-900/60','https://upload.wikimedia.org/wikipedia/pt/9/9c/Cabra-marcado-para-morrer-poster03.png');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('narradores-de-jave','Narradores de Javé',2003,'Eliane Caffé',7.6,'Moradores de uma cidade ameaçada por uma barragem tentam escrever sua história para impedir que o lugar seja destruído.','Use para patrimônio cultural, memória oral e deslocamento por grandes obras.','Narradores de Javé (2003) evidencia que a memória oral é patrimônio que legitima o direito de comunidades a seu território.','desenvolvimento','from-amber-400/30 to-teal-900/50','https://upload.wikimedia.org/wikipedia/pt/3/35/Narradores_de_Jav%C3%A9.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('terra-estrangeira','Terra Estrangeira',1995,'Walter Salles e Daniela Thomas',7.5,'Em 1990, após o confisco da poupança, um jovem paulista emigra para Lisboa e se envolve em tráfico de diamantes.','Serve para emigração, crise econômica e identidade nacional.','Terra Estrangeira (1995) mostra que a crise econômica empurra brasileiros ao exterior e levanta a questão de pertencimento nacional.','desenvolvimento','from-violet-600/30 to-emerald-900/50','https://upload.wikimedia.org/wikipedia/pt/d/db/Terra_Estrangeira.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('abril-despedacado','Abril Despedaçado',2001,'Walter Salles',7.6,'No sertão brasileiro de 1910, duas famílias se enfrentam em uma disputa de honra que se repete por gerações.','Use para ciclos de violência, tradição e liberdade individual.','Abril Despedaçado (2001) revela que a violência herdada por tradição aprisiona gerações e só termina quando alguém ousa romper o ciclo.','desenvolvimento','from-rose-400/30 to-amber-900/50','https://upload.wikimedia.org/wikipedia/pt/b/b5/AbrilDespeda%C3%A7ado.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('zootopia','Zootopia',2016,'Byron Howard e Rich Moore',8.0,'Em uma cidade de animais, uma coelha policial investiga um caso e enfrenta preconceitos.','Serve para preconceito, estereótipos e convivência na diversidade. Funciona bem para introduzir o tema.','Zootopia (2016) usa a ficção para mostrar que estereótipos geram discriminação e que a convivência na diversidade exige combater os próprios preconceitos.','introducao','from-lime-500/30 to-stone-900/60','https://upload.wikimedia.org/wikipedia/pt/3/3b/ZootopiaOficialPoster.jpg');

